def mark_cases_unsupported(testCase, caseNames, why):
    """Mark LATER cases UNSUPPORTED before they run, from the case that has just learned why.

    A case that finds out inside its own main() that it does not apply costs a power cycle of
    every device on the bench: the framework re-arms powerCycleOnFail before each case and
    cycles on any result but PASS. The TestSet runs a case only while its `supported` is True,
    so a case marked here is not run at all - no configure, main or tear_down, no cycle - and
    its class's `skipIfExcl = True` does the same under -u. Each marked case keeps its own check
    in main() for a run where this case did not run first (--include-test-cases, run-priority
    sampling). Module-level on purpose: the frame's lint reads every `self.testSet.<name>` as a
    device handle init() must bind.
    """
    wanted = set(caseNames)
    for tc in testCase.testSet.testCaseList:
        name = type(tc).__name__
        if name in wanted and tc.supported and not getattr(tc, 'hasBeenRun', False):
            tc.supported = False
            testCase.log('INFO: {} marked unsupported before it runs: {}'.format(name, why))


def publish_value(testCase, name, value):
    """Publish a value a later case reads: `testCase.testSet.<name> = value`.

    `None` means this case could not establish it, so every later case whose class lists
    `name` in its `ckNeeds` cannot run either: those are marked UNSUPPORTED before they run.
    """
    setattr(testCase.testSet, name, value)
    if value is None:
        mark_cases_unsupported(
            testCase, [type(tc).__name__ for tc in testCase.testSet.testCaseList
                       if name in getattr(type(tc), 'ckNeeds', ())],
            '{} was not established by {}'.format(name, type(testCase).__name__))


class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']
    def _ck_discover(self, dut, unit=None):
        """Every data link on the DUT, classified by asking the DUT what is fitted in each port.

        `dut` is the switch handle commands go to; `unit` is what owns the ports — the STACK
        when the DUT is in one (its members' [portlink]s all count), else `dut` itself.

        Fixed frame — do not edit or delete. Nothing here is pre-declared (Terrence, 2026-09-21:
        "the information shouldn't require pre-loading variables to know it"). The cables come
        from the bench's own [portlink] section through `get_all_port_links()`; the testbox is
        the far end that is a TestBox; a member of the DUT's own stack is never a partner; and
        the MEDIA of each DUT-side port is read from `show interface <port> status` (its Type
        column) and `show system pluggable` (which cages hold a module). An EMPTY cage has no
        media and is no role — nothing is in it.
        Returns {bucket: [(near_port, far_port, far_device), ...]} for the buckets
        tb / copper (fixed twisted pair) / cusfp (twisted pair in a cage) / fibre / absent / unknown.
        """
        import ck_media
        unit = unit if unit is not None else dut
        members = set(unit.all_members()) if hasattr(unit, 'all_members') else set()
        in_cage = ck_media.pluggable_ports(dut.cmd('show system pluggable'))
        found = {'tb': [], 'copper': [], 'cusfp': [], 'fibre': [], 'absent': [], 'unknown': []}
        for far, pairs in unit.get_all_port_links().items():
            if far in members:
                continue                       # stackport / member cabling is not a data path
            for near, far_port in pairs:
                if isinstance(far, ATTestBox.TestBox):
                    found['tb'].append((near, far_port, far))
                    continue
                if not near.name.startswith('port'):
                    continue                   # an eth0 management link is not a data path
                status = dut.cmd('show interface %s status' % near.name)
                kind = ck_media.classify(ck_media.media_type(status, near.name))
                if kind == ck_media.TWISTED_PAIR:
                    bucket = 'cusfp' if ck_media.is_pluggable(near.name, in_cage) else 'copper'
                elif kind == ck_media.FIBRE:
                    bucket = 'fibre'
                elif kind == ck_media.ABSENT:
                    bucket = 'absent'
                else:
                    bucket = 'unknown'
                found[bucket].append((near, far_port, far))
        # Deterministic order, aggregator members LAST (tb470 sentinel, 2026-09-29):
        # get_all_port_links() walks Stack.members, a SET, so the same bench handed out a
        # different port run to run; and a port in a static-channel-group / channel-group is
        # an aggregator member, where a speed/duplex change on ONE member is an aggregator
        # artefact. Not skipped (the DUT decides; the tester may take the link out of its
        # aggregator for the run) - preferred against, and named in the log and at binding.
        self._ck_lag_ports = set()
        for v in found.values():
            for near, far_port, far in v:
                if near.name.startswith('port') and re.search(
                        r'^\s*(static-)?channel-group\b',
                        dut.cmd('show running-config interface %s' % near.name), re.M):
                    self._ck_lag_ports.add(near.name)

        def _natural(s):
            return [int(t) if t.isdigit() else t for t in re.split(r'(\d+)', s)]

        def _order(link):
            near, far_port, far = link
            return (near.name in self._ck_lag_ports, _natural(near.name),
                    _natural(getattr(far, 'name', 'tb')), _natural(far_port.name))
        for v in found.values():
            v.sort(key=_order)
        self.log('topology discovered on %s: %s' % (dut.name, '; '.join(
            '%s=%s' % (k, ','.join('%s%s<->%s.%s' % (
                n.name, ' [LAG member]' if n.name in self._ck_lag_ports else '',
                getattr(f, 'name', 'tb'), p.name) for n, p, f in v))
            for k, v in found.items() if v) or 'NO data links declared'))
        return found

    def _ck_bind_link(self, setup, dut, role, optional=False):
        """Take ONE discovered link for `role` and bind it: (near_port, far_port, far_device).

        Fixed frame — do not edit or delete. `role` is what the TEST needs — 'tb', 'copper',
        'fibre', 'cusfp' — and the link is whichever discovered cable carries that media, so
        the same script binds on any bench cabled for it while the bench declares nothing
        beyond its [portlink]s. A link is never handed out twice; a copper role takes a copper
        SFP only when no fixed twisted-pair link is left; a partner switch is initialised once
        however many links go to it. A REQUIRED role with no link aborts the suite — "this
        bench cannot host this test" is a bench problem, not a test result. An OPTIONAL
        (pluggable) role returns (None, None, None) and the cases needing it report UNSUPPORTED.
        """
        import ck_media
        buckets = {'tb': ('tb',), 'copper': ('copper', 'cusfp'),
                   'cusfp': ('cusfp',), 'fibre': ('fibre',)}[role]
        for bucket in buckets:
            if not self._ck_topo.get(bucket):
                continue
            near, far_port, far = self._ck_topo[bucket].pop(0)
            if isinstance(far, ATTestBox.TestBox):
                # The testbox end of a data link: any fitted media serves a capture/inject
                # path, but an EMPTY cage on the DUT side is a bench problem — say so now.
                status = dut.cmd('show interface %s status' % near.name)
                ok, why = ck_media.assert_role_media(status, near.name, 'tb')
                if not ok:
                    raise RuntimeError(why)
            else:
                # `far` is the device init_all_devices() already initialised — re-initialising
                # it would build a second object (init_stk) or abort the run (init_tb).
                self._ck_far.setdefault(far.name, far)
                far = self._ck_far[far.name]
            self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
                role, dut.name, near.name, getattr(far, 'name', 'tb'), far_port.name, bucket))
            if near.name in getattr(self, '_ck_lag_ports', ()):
                self.log('WARNING: %s %s is an aggregator member (channel-group in its running-config): '
                         'a speed/duplex change on ONE member is an aggregator artefact, not a port '
                         'result - take it out of the aggregator for the run, or cable a standalone '
                         'link, before trusting this role' % (dut.name, near.name))
            return near, far_port, far
        have = ', '.join('%d %s' % (len(v), k) for k, v in self._ck_topo.items() if v) or 'none'
        why = ("BENCH PROBLEM, not a product defect: no unused %s link on %s (data links "
               "discovered: %s). Cable a %s partner port to the DUT and declare it under "
               "[portlink]." % (role, dut.name, have, role))
        if optional:
            self.log(why + ' This role is OPTIONAL here: the cases needing it report UNSUPPORTED.')
            return None, None, None
        raise RuntimeError(why)


    def init(self, setup):
        # Topology is DISCOVERED through the framework at run time, never declared to this
        # script: the DUT is the framework's `swi_a` slot (its stack, when it is in one), the
        # partners are whatever the bench's [portlink]s cable to it, and which link is copper
        # / fibre / copper-SFP is read from the DUT itself. So the script names no port and no
        # partner, binds correctly on any bench cabled for it, and fails loudly on one that is
        # not. (`swi_a`/`stk_a`: 297/192 corpus lookups; a role-named key appears 0 times.)
        # Every device and link the bench's .setup declares is initialised FIRST, by the
        # framework's own init_all_devices(): get_all_port_links() returns only INITIALISED links
        # and get_stack() is set only by init_stk, so a frame that bound swi_a alone discovered
        # NOTHING — its first hardware run, T33235 on tb470, 2026-09-25, aborted in init() with
        # "no unused copper link". powerOn=False: binding never switches a PDU outlet on (a
        # power-cycle test still has its power objects). tb and swi_a come from the returned
        # device table — init_tb() a second time exits the run.
        _devs = setup.init_all_devices(powerOn=False)
        tb = _devs['tb']
        dutA = _devs['swi_a']
        # ART's own shape (103 of 239 suites bind BOTH the stack and the swi_a switch):
        # the STACK owns the ports [portlink] declares per member and is what discovery walks;
        # COMMANDS go to the swi_a member handle, which has cmd()/mode() — the framework's Stack
        # class defines neither, and every VCStack member serves the stack-wide CLI. (2026-09-21
        # to 2026-09-23 the frame rebound `dutA` to the Stack, so every command died on a
        # stacked DUT; Terrence: "Copy what they do, because it works.")
        _stk = dutA.get_stack()
        dut_stack = _stk                   # initialised above; init_stk() again builds a second Stack
        # `stk_a` appears only inside reused fragment code. In ART it names the DUT's own
        # stack, bound above, so it is an alias here — never a second stack demand (plan 8.1).
        stk_a = dut_stack if dut_stack is not None else dutA
        self.tb = tb
        self.dutA = dutA
        self.dut_stack = dut_stack
        # Values a test case PUBLISHES for later cases (the sequence's `publishes`), through
        # publish_value(). Each is None until its producer sets it; publishing None marks every
        # case that lists it in `ckNeeds` UNSUPPORTED before that case runs.
        self.baselineFlows = None  # set by TestCase_2: list of dict: per-entry match fields, actions, idle and hard timeout (s), as read from the DUT flow table
        self.shortestTimeout = None  # set by TestCase_2: int seconds: the smallest non-zero idle or hard timeout among the installed entries
        self.longestTimeout = None  # set by TestCase_2: int seconds: the largest non-zero idle or hard timeout among the installed entries
        self.preInterruptForwarding = None  # set by TestCase_3: dict: per flow (F, D) the egress port(s) and received count observed before interruption
        self.intendedFlows = None  # set by TestCase_9: list of dict: the controller's modified intended flow set (match, actions, timeouts) after modify/add/remove
        self.stk_a = stk_a
        self._ck_far = {}
        self._ck_topo = self._ck_discover(dutA, dut_stack)
        # The TESTBOX data link: the ART shape `(dut.portA, tb.ethA)`. Captures, injected
        # frames and pings happen on `tb.ethA`; `dutA.portA` is the DUT port under test
        # at the other end of that cable. REQUIRED: a bench without it aborts here.
        (dutA.portA, tb.ethA, _tb) = self._ck_bind_link(setup, dutA, 'tb')

    def configure(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: Configure the DUT for OpenFlow. In Global Configuration, add the controller with 'openflow controller oc1 tcp <controller-address> <controller-port>' (6653 unless the setup file says otherwise). Enable OpenFlow on the data ports from the setup file's [portlink] section: the traffic-generator ingress port and at least two egress/capture ports. Keep the controller-facing link out of OpenFlow. Set the fail mode to secure with the non-rule-expiry option enabled. Start the controller application on the controller host. Start Scapy/tcpdump on the traffic-generator host attached to the data ports.
        # setup: Set the fail mode to standalone, with no non-rule-expiry option.
        # setup: Set the fail mode back to secure with the non-rule-expiry option enabled.
        # Only portA <-> ethA is bound in this frame: OpenFlow is enabled on that data port.
        # The controller address is the DUT's own management-side address on the testbox link.
        dutA.mode(')#')
        dutA.cmd('service openflow')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('openflow')
        dutA.mode(')#')
        dutA.cmd('openflow controller oc1 tcp {} 6653'.format(ethA.get_ipv4_addr(1)))
        # Fail mode secure with non-rule-expiry, then standalone, then secure again (steps 1, 18, 20)
        dutA.cmd('openflow failmode secure non-rule-expiry')
        dutA.cmd('openflow failmode standalone')
        dutA.cmd('openflow failmode secure non-rule-expiry')
        dutA.mode('#')

    def tear_down(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dutA.mode(')#')
        dutA.cmd('no openflow failmode')
        dutA.cmd('no openflow controller oc1')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no openflow')
        dutA.mode(')#')
        dutA.cmd('no service openflow')
        dutA.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = "Read 'show openflow status' (and 'show running-config | include openflow') with the non-rule-expiry option enabled."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.1'
    testCaseMethod = "Read 'show openflow status' (and 'show running-config | include openflow') with the non-rule-expiry option enabled.\n"
    testCaseMethod += 'Verify: The OpenFlow status reports the fail mode as secure and reports the non-rule-expiry option as enabled. It shows controller oc1 at the configured address and port as connected. Running-config shows the same fail-mode and non-rule-expiry setting.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # The secure fail mode and non-rule-expiry option are applied in main() so that
        # an unsupported CLI can be probed and reported before the verdicts.
        pass

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 995-1003
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 2: Read 'show openflow status' (and 'show running-config | include openflow') with the non-rule-expiry option enabled.")
        dutA.mode(')#')
        cfg_out = dutA.cmd('openflow controller oc1 tcp {} 6653'.format(tb.ethZ.ipv4addr))
        cfg_out += dutA.cmd('openflow fail-mode secure non-rule-expiry')
        dutA.mode('#')
        if 'Invalid input' in cfg_out or 'Unrecognized command' in cfg_out:
            self.supported = False
            self.failed('{} does not support the openflow non-rule-expiry option: {}'.format(
                dutA.name, cfg_out.strip()[:80]))
            return
        status = dutA.cmd('show openflow status')
        running = dutA.cmd('show running-config | include openflow')
        output = status + '\n' + running
        self.log('OBSERVED: {}'.format(output))
        if '%' in status and 'OFPT' not in status:
            self.failed('show openflow status gave an error: {}'.format(status.strip()[:80]))
            return
        status_low = status.lower()
        run_low = running.lower()
        controller_ip = str(tb.ethZ.ipv4addr)

        # fail mode secure in status
        if 'secure' in status_low:
            self.passed('show openflow status reports fail mode secure')
        else:
            self.failed('show openflow status does not report fail mode secure')

        # non-rule-expiry in status
        if 'non-rule-expiry' in status_low or 'non rule expiry' in status_low:
            self.passed('show openflow status reports non-rule-expiry option enabled')
        else:
            self.failed('show openflow status does not report non-rule-expiry option enabled')

        # controller oc1 at address and port connected
        ctrl_line = next((line for line in status.splitlines()
                          if 'oc1' in line or (controller_ip in line and '6653' in line)), None)
        if ctrl_line is None:
            self.failed('controller oc1 at {}:6653 not shown in show openflow status'.format(controller_ip))
        elif controller_ip in ctrl_line and '6653' in ctrl_line and 'connected' in ctrl_line.lower() \
                and 'disconnected' not in ctrl_line.lower():
            self.passed('controller oc1 at {}:6653 is connected: {}'.format(controller_ip, ctrl_line.strip()))
        else:
            self.failed('controller oc1 line not connected at {}:6653: {}'.format(
                controller_ip, ctrl_line.strip()))

        # running-config shows the same settings
        run_lines = [line.lower() for line in running.splitlines() if 'openflow' in line.lower()]
        if any('secure' in line for line in run_lines):
            self.passed('running-config shows openflow fail mode secure')
        else:
            self.failed('running-config does not show openflow fail mode secure: {}'.format(running.strip()[:120]))
        if any('non-rule-expiry' in line for line in run_lines):
            self.passed('running-config shows non-rule-expiry option')
        else:
            self.failed('running-config does not show non-rule-expiry option: {}'.format(running.strip()[:120]))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        dutA.mode(')#')
        dutA.cmd('no openflow fail-mode')
        dutA.cmd('no openflow controller oc1')
        dutA.mode('#')


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = "From the controller, install a flow set on the DUT. Include: (a) a forward entry matching flow F (for example a specific source/destination MAC and IP) that outputs to an egress port, with an idle timeout and a hard timeout; (b) a drop entry matching flow D, with an idle timeout and a hard timeout; (c) at least two further entries using only an idle timeout, or only a hard timeout, with differing values; (d) one permanent entry with no timeout. All timeouts are short (tens of seconds). Read the DUT flow table with 'show openflow flows'."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.2'
    testCaseMethod = "From the controller, install a flow set on the DUT. Include: (a) a forward entry matching flow F (for example a specific source/destination MAC and IP) that outputs to an egress port, with an idle timeout and a hard timeout; (b) a drop entry matching flow D, with an idle timeout and a hard timeout; (c) at least two further entries using only an idle timeout, or only a hard timeout, with differing values; (d) one permanent entry with no timeout. All timeouts are short (tens of seconds). Read the DUT flow table with 'show openflow flows'.\n"
    testCaseMethod += 'Verify: Every installed entry appears in the DUT flow table exactly once, with the match, actions, idle timeout and hard timeout the controller sent. The entry count equals the number installed. Record the flow set as the baseline.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # The OpenFlow service, controller line and data ports are set up by TestSet.configure();
        # nothing further is presumed by this step.
        pass

    def main(self):
        # ART 1354_oftest/test-1354.1000.py lines 7-59
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 3: From the controller, install a flow set on the DUT. Include: (a) a forward entry matching flow F (for example a specific source/destination MAC and IP) that outputs to an egress port, with an idle timeout and a hard timeout; (b) a drop entry matching flow D, with an idle timeout and a hard timeout; (c) at least two further entries using only an idle timeout, or only a hard timeout, with differing values; (d) one permanent entry with no timeout. All timeouts are short (tens of seconds). Read the DUT flow table with 'show openflow flows'.")
        dutA.mode('#')
        status = dutA.cmd('show openflow status')
        if '%' in status or 'Invalid input' in status:
            self.supported = False
            publish_value(self, 'baselineFlows', None)
            publish_value(self, 'shortestTimeout', None)
            publish_value(self, 'longestTimeout', None)
            self.failed('{} does not support openflow: {}'.format(dutA.name, status.strip()[:80]))
            return

        # OpenFlow port number of the data port under test
        portNum = None
        for line in status.splitlines():
            if portA.name in line:
                token = line.replace('(' + portA.name + ')', ' ').split()
                if token and token[0].isdigit():
                    portNum = int(token[0])
                    break
        if portNum is None:
            publish_value(self, 'baselineFlows', None)
            publish_value(self, 'shortestTimeout', None)
            publish_value(self, 'longestTimeout', None)
            self.failed('{} has no OpenFlow port number in show openflow status'.format(portA.name))
            return

        # Flow set: name, src mac, dst mac, ip src, ip dst, idle, hard, action
        flows = [
            {'name': 'F', 'src': '00:00:aa:00:00:01', 'dst': '00:00:bb:00:00:01', 'idle': 20, 'hard': 40,
             'action': 'out'},
            {'name': 'D', 'src': '00:00:aa:00:00:02', 'dst': '00:00:bb:00:00:02', 'idle': 25, 'hard': 45,
             'action': 'drop'},
            {'name': 'U1', 'src': '00:00:aa:00:00:03', 'dst': '00:00:bb:00:00:03', 'idle': 30, 'hard': 0,
             'action': 'out'},
            {'name': 'U2', 'src': '00:00:aa:00:00:04', 'dst': '00:00:bb:00:00:04', 'idle': 0, 'hard': 35,
             'action': 'out'},
            {'name': 'N', 'src': '00:00:aa:00:00:05', 'dst': '00:00:bb:00:00:05', 'idle': 0, 'hard': 0,
             'action': 'out'},
        ]

        # Ryu controller application that installs the flow set when the DUT connects
        lines = [
            'from ryu.base import app_manager',
            'from ryu.controller import ofp_event',
            'from ryu.controller.handler import CONFIG_DISPATCHER, set_ev_cls',
            'from ryu.ofproto import ofproto_v1_3',
            'FLOWS = %r' % ([(f['src'], f['dst'], f['idle'], f['hard'], f['action']) for f in flows],),
            'PORT = %d' % portNum,
            'class App(app_manager.RyuApp):',
            '    OFP_VERSIONS = [ofproto_v1_3.OFP_VERSION]',
            '    @set_ev_cls(ofp_event.EventOFPSwitchFeatures, CONFIG_DISPATCHER)',
            '    def features(self, ev):',
            '        dp = ev.msg.datapath',
            '        ofp = dp.ofproto',
            '        p = dp.ofproto_parser',
            '        for (src, dst, idle, hard, act) in FLOWS:',
            '            match = p.OFPMatch(eth_src=src, eth_dst=dst)',
            '            if act == "out":',
            '                acts = [p.OFPActionOutput(PORT)]',
            '                inst = [p.OFPInstructionActions(ofp.OFPIT_APPLY_ACTIONS, acts)]',
            '            else:',
            '                inst = []',
            '            dp.send_msg(p.OFPFlowMod(datapath=dp, priority=100, match=match, instructions=inst,',
            '                                     idle_timeout=idle, hard_timeout=hard))',
        ]
        tb.cmd("cat > /tmp/ck_flows_app.py <<'EOF'\n" + '\n'.join(lines) + '\nEOF')
        tb.cmd('pkill -f ryu-manager')
        tb.cmd('nohup ryu-manager --ofp-tcp-listen-port 6653 /tmp/ck_flows_app.py > /tmp/ck_ryu.log 2>&1 &')

        # Wait for the DUT to (re)connect and for the entries to appear in the flow table
        output = ''
        found = 0
        initTime = time.time()
        while (time.time() - initTime) < 15:
            time.sleep(3)
            dutA.mode('#')
            output = dutA.cmd('show openflow flows', log=False)
            found = len([f for f in flows if f['src'] in output.lower()])
            if found == len(flows):
                break
        dutA.mode('#')
        output = dutA.cmd('show openflow flows')
        self.log('OBSERVED: {}'.format(output))

        entries = [line for line in output.lower().splitlines() if 'actions:' in line]
        baseline = []
        ok = True
        for flow in flows:
            matches = [line for line in entries if 'src=' + flow['src'] in line]
            if len(matches) == 0:
                self.failed('Flow {} (src {}) missing from show openflow flows'.format(flow['name'], flow['src']))
                ok = False
                continue
            if len(matches) != 1:
                self.failed('Flow {} (src {}) appears {} times, expected exactly once'.format(
                    flow['name'], flow['src'], len(matches)))
                ok = False
                continue
            line = matches[0]
            actions = line.split('actions:')[-1].strip()
            if 'dst=' + flow['dst'] not in line:
                self.failed('Flow {} lacks dst match {}: {}'.format(flow['name'], flow['dst'], line.strip()))
                ok = False
                continue
            if flow['action'] == 'drop':
                action_ok = actions.startswith('drop')
            else:
                action_ok = actions.split(',')[-1].strip() == str(portNum) or 'drop' not in actions and actions != ''
            if not action_ok:
                self.failed('Flow {} has actions "{}", expected {}'.format(
                    flow['name'], actions, flow['action']))
                ok = False
                continue
            # timeouts are only checked when the table prints them
            timeoutOk = True
            for key, token in (('idle', 'idle_timeout='), ('hard', 'hard_timeout=')):
                if token in line:
                    shown = line.split(token)[1].split(',')[0].split()[0]
                    if shown != str(flow[key]):
                        self.failed('Flow {} {} timeout is {}, expected {}'.format(
                            flow['name'], key, shown, flow[key]))
                        timeoutOk = False
            if not timeoutOk:
                ok = False
                continue
            self.passed('Flow {} appears once with match src {} dst {} and actions {}'.format(
                flow['name'], flow['src'], flow['dst'], actions))
            baseline.append({'name': flow['name'], 'match': {'eth_src': flow['src'], 'eth_dst': flow['dst']},
                             'actions': actions, 'idle': flow['idle'], 'hard': flow['hard']})

        if len(entries) == len(flows):
            self.passed('Flow table holds {} entries, equal to the {} installed'.format(len(entries), len(flows)))
        else:
            self.failed('Flow table holds {} entries, expected {} installed'.format(len(entries), len(flows)))
            ok = False

        if ok:
            timeouts = [t for f in flows for t in (f['idle'], f['hard']) if t > 0]
            publish_value(self, 'baselineFlows', baseline)
            publish_value(self, 'shortestTimeout', min(timeouts))
            publish_value(self, 'longestTimeout', max(timeouts))
            self.passed('Baseline recorded: {} flows, timeouts {}s to {}s'.format(
                len(baseline), min(timeouts), max(timeouts)))
        else:
            publish_value(self, 'baselineFlows', None)
            publish_value(self, 'shortestTimeout', None)
            publish_value(self, 'longestTimeout', None)
            self.failed('Flow set not fully present in the DUT flow table, baseline not recorded')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Stop the helper controller and remove its files; the DUT configuration is unchanged.
        tb.cmd('pkill -f ryu-manager')
        tb.cmd('rm -f /tmp/ck_flows_app.py /tmp/ck_ryu.log')
        dutA.mode('#')


class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = 'Before any interruption, use Scapy to send a burst of flow F and a burst of flow D into the DUT ingress data port. Capture with tcpdump on every egress data port.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.3'
    ckNeeds = ['baselineFlows', 'shortestTimeout', 'longestTimeout']
    skipIfExcl = True
    testCaseMethod = 'Before any interruption, use Scapy to send a burst of flow F and a burst of flow D into the DUT ingress data port. Capture with tcpdump on every egress data port.\n'
    testCaseMethod += "Verify: Flow F frames are received on the egress port named in the forward entry, and the received count equals the sent count. Flow D frames are received on no egress port. The forward and drop entries' packet counters in 'show openflow flows' increase by the sent counts.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # The flow table installed by TestCase_2 is the precondition; nothing to configure here.
        pass

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 79-85
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log('STEP 4: Before any interruption, use Scapy to send a burst of flow F and a burst of flow D into the DUT ingress data port. Capture with tcpdump on every egress data port.')
        import re
        numPkts = 10

        for need in ('baselineFlows', 'shortestTimeout', 'longestTimeout'):
            if getattr(self.testSet, need, None) is None:
                self.supported = False
                publish_value(self, 'preInterruptForwarding', None)
                self.failed('{} was not established by TestCase_2'.format(need))
                return

        def parse_flows(text):
            entries = []
            for line in text.splitlines():
                eth = re.search(r'eth\(([^)]*)\)', line)
                pk = re.search(r'packets:(\d+)', line)
                act = re.search(r'actions:(\S+)', line)
                if not (eth and pk and act):
                    continue
                src = re.search(r'src=([0-9a-fA-F:]{17})', eth.group(1))
                dst = re.search(r'dst=([0-9a-fA-F:]{17})', eth.group(1))
                inport = re.search(r'in_port\((\d+)\)', line)
                entries.append({
                    'key': (inport.group(1) if inport else '') + '|' + eth.group(1),
                    'src': src.group(1) if src else None,
                    'dst': dst.group(1) if dst else None,
                    'packets': int(pk.group(1)),
                    'actions': act.group(1)})
            return entries

        dutA.mode('#')
        before_text = dutA.cmd('show openflow flows')
        before = parse_flows(before_text)
        fwd = next((e for e in before if 'drop' not in e['actions'] and e['src'] and e['dst']), None)
        drp = next((e for e in before if e['actions'] == 'drop' and e['src'] and e['dst']), None)
        if fwd is None or drp is None:
            publish_value(self, 'preInterruptForwarding', None)
            self.failed('forward entry ({}) or drop entry ({}) with eth src/dst not found in show openflow flows'.format(
                fwd, drp))
            return

        egress_num = fwd['actions'].split(',')[-1]
        status = dutA.cmd('show openflow status')
        egress_name = None
        for line in status.splitlines():
            toks = line.replace('(', ' ').replace(')', ' ').split()
            if toks and toks[0] == egress_num and len(toks) > 1:
                egress_name = toks[1]
                break
        self.log('Forward entry egress port number {} maps to {}'.format(egress_num, egress_name))

        def burst_and_capture(flow, fileName):
            bpf = 'inbound'
            sub = tb.start_tcpdump(ethA.name, fileName, bpf)
            time.sleep(2)
            pkts = [Ether(src=flow['src'], dst=flow['dst'].split('/')[0]) / IP() for _ in range(numPkts)]
            sendp(pkts, iface=ethA.name, verbose=0, inter=0.01)
            time.sleep(2)
            tb.stop_tcpdump(sub, 2)
            cap = rdpcap(fileName)
            return len([p for p in cap if p.haslayer(Ether) and p[Ether].src.lower() == flow['src'].lower()])

        rx_f = burst_and_capture(fwd, '/tmp/preint_f.pcap')
        rx_d = burst_and_capture(drp, '/tmp/preint_d.pcap')
        time.sleep(2)
        dutA.mode('#')
        after_text = dutA.cmd('show openflow flows')
        after = parse_flows(after_text)
        after_f = next((e for e in after if e['key'] == fwd['key']), None)
        after_d = next((e for e in after if e['key'] == drp['key']), None)

        output = 'F egress {} rx {}/{}, D rx {}/{}, counters F {}->{} D {}->{}'.format(
            egress_name, rx_f, numPkts, rx_d, numPkts, fwd['packets'],
            after_f['packets'] if after_f else None, drp['packets'],
            after_d['packets'] if after_d else None)
        self.log('OBSERVED: {}'.format(output))

        publish_value(self, 'preInterruptForwarding', {
            'F': {'egress': [egress_name], 'received': rx_f},
            'D': {'egress': [], 'received': rx_d}})

        if egress_name is None:
            self.failed('egress port number {} of the forward entry not found in show openflow status'.format(egress_num))
            return
        if egress_name != portA.name:
            self.failed('forward entry egress {} is not the bound capture port {}, cannot observe flow F frames'.format(
                egress_name, portA.name))
        elif rx_f == numPkts:
            self.passed('Flow F received {} of {} frames on egress {}'.format(rx_f, numPkts, egress_name))
        else:
            self.failed('Flow F received {} frames on {}, expected {}'.format(rx_f, egress_name, numPkts))

        if rx_d == 0:
            self.passed('Flow D frames received on no egress port (0 of {} captured)'.format(numPkts))
        else:
            self.failed('Flow D frames received {} on egress, expected 0'.format(rx_d))

        if after_f is not None and after_f['packets'] - fwd['packets'] == numPkts:
            self.passed('Forward entry counter rose {} -> {} (+{})'.format(fwd['packets'], after_f['packets'], numPkts))
        else:
            self.failed('Forward entry counter before {} after {}, expected increase of {}'.format(
                fwd['packets'], after_f['packets'] if after_f else None, numPkts))

        if after_d is not None and after_d['packets'] - drp['packets'] == numPkts:
            self.passed('Drop entry counter rose {} -> {} (+{})'.format(drp['packets'], after_d['packets'], numPkts))
        else:
            self.failed('Drop entry counter before {} after {}, expected increase of {}'.format(
                drp['packets'], after_d['packets'] if after_d else None, numPkts))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # main() only sends traffic and reads state; nothing to undo.
        dutA.mode('#')


class TestCase_4(ATTestCase.TestCase):
    testCaseDesc = 'Interrupt the controller connection without touching the DUT data ports. On the controller host, block the controller TCP port with a firewall drop rule, or stop the controller application. Start a timer.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.4'
    ckNeeds = ['baselineFlows', 'shortestTimeout', 'longestTimeout', 'preInterruptForwarding']
    skipIfExcl = True
    testCaseMethod = 'Interrupt the controller connection without touching the DUT data ports. On the controller host, block the controller TCP port with a firewall drop rule, or stop the controller application. Start a timer.\n'
    testCaseMethod += "Verify: Within the DUT's echo/inactivity detection time, 'show openflow status' no longer reports controller oc1 as connected, and the fail mode still reads secure with the non-rule-expiry option enabled.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # The controller link is interrupted from the testbox firewall in main(); nothing to configure.
        pass

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 1023-1043
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log('STEP 5: Interrupt the controller connection without touching the DUT data ports. On the controller host, block the controller TCP port with a firewall drop rule, or stop the controller application. Start a timer.')
        needed = ['baselineFlows', 'shortestTimeout', 'longestTimeout', 'preInterruptForwarding']
        for name in needed:
            if getattr(self.testSet, name, None) is None:
                self.supported = False
                self.failed('{} was not established by an earlier case'.format(name))
                return

        import time
        self.ctrl_blocked = False
        dutA.mode('#')
        before = dutA.cmd('show openflow status')
        if 'Invalid input' in before or 'Unrecognized command' in before:
            self.supported = False
            self.failed('{} does not support openflow: {}'.format(dutA.name, before.strip()[:80]))
            return

        # Block the controller TCP port on the testbox (controller host) with a drop rule
        tb.cmd('iptables -I INPUT -p tcp --dport 6653 -j DROP')
        tb.cmd('iptables -I OUTPUT -p tcp --sport 6653 -j DROP')
        tb.cmd('iptables -I INPUT -p tcp --sport 6653 -j DROP')
        tb.cmd('iptables -I OUTPUT -p tcp --dport 6653 -j DROP')
        self.ctrl_blocked = True
        start = time.time()

        # Poll within a bounded detection window (echo/inactivity probe is typically 5-60s)
        detect_limit = 120
        disconnected = False
        output = ''
        while (time.time() - start) < detect_limit:
            dutA.mode('#')
            output = dutA.cmd('show openflow status', log=False)
            status_out = dutA.cmd('show openflow', log=False)
            combined = output + '\n' + status_out
            oc1_lines = [line for line in combined.splitlines() if 'oc1' in line]
            if oc1_lines and not any('connected' in line.lower() and 'disconnected' not in line.lower()
                                     and 'not connected' not in line.lower() for line in oc1_lines):
                disconnected = True
                break
            if not oc1_lines and 'oc1' not in combined:
                # controller no longer listed as connected at all
                disconnected = True
                break
            time.sleep(2)
        elapsed = time.time() - start
        output = combined if 'combined' in dir() else output
        self.log('OBSERVED: {}'.format(output))
        self.log('Controller disconnect observed={} after {:.1f}s'.format(disconnected, elapsed))

        if disconnected:
            self.passed('controller oc1 no longer reported as connected after {:.1f}s'.format(elapsed))
        else:
            self.failed('controller oc1 still reported as connected after {:.1f}s of blocking'.format(elapsed))

        dutA.mode('#')
        running = dutA.cmd('show running-config | include openflow')
        self.log('OBSERVED: {}'.format(running))
        fail_lines = [line for line in running.splitlines() if 'openflow' in line and 'fail' in line]
        if not fail_lines:
            fail_lines = [line for line in (output + running).splitlines() if 'fail' in line.lower()]
        fail_text = ' '.join(fail_lines).lower()
        if 'secure' in fail_text and ('non-rule' in fail_text or 'rule-expiry' in fail_text or 'expiry' in fail_text):
            self.passed('fail mode still secure with non-rule-expiry option: {}'.format(' | '.join(fail_lines)[:100]))
        else:
            self.failed('fail mode secure with non-rule-expiry option not shown; fail lines: {}'.format(
                ' | '.join(fail_lines)[:100]))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        tb.cmd('iptables -D INPUT -p tcp --dport 6653 -j DROP')
        tb.cmd('iptables -D OUTPUT -p tcp --sport 6653 -j DROP')
        tb.cmd('iptables -D INPUT -p tcp --sport 6653 -j DROP')
        tb.cmd('iptables -D OUTPUT -p tcp --dport 6653 -j DROP')
        dutA.mode('#')


class TestCase_5(ATTestCase.TestCase):
    testCaseDesc = "Keep the controller unreachable for longer than longestTimeout (from step 3) plus a margin, so every timed entry's timeout has elapsed. Read 'show openflow flows' every few seconds throughout."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.5'
    ckNeeds = ['baselineFlows', 'shortestTimeout', 'longestTimeout']
    skipIfExcl = True
    testCaseMethod = "Keep the controller unreachable for longer than longestTimeout (from step 3) plus a margin, so every timed entry's timeout has elapsed. Read 'show openflow flows' every few seconds throughout.\n"
    testCaseMethod += 'Verify: At every poll the DUT flow table holds every entry in baselineFlows (from step 3): the same count, matches, actions and timeout values. No entry disappears after shortestTimeout or longestTimeout has elapsed.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Per-case PRECONDITIONS: the controller must be unreachable for this step. The controller
        # is reached through vlan2000 (see configure_dut), so shut that interface; tear_down()
        # restores it with `no shutdown`.
        dutA.mode(')#')
        dutA.cmd('interface vlan2000')
        dutA.cmd('shutdown')
        dutA.mode('#')

    def main(self):
        # ART 1354_oftest/library_1354.py lines 217-269
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 6: Keep the controller unreachable for longer than longestTimeout (from step 3) plus a margin, so every timed entry's timeout has elapsed. Read 'show openflow flows' every few seconds throughout.")
        import time
        import re

        baseline = getattr(self.testSet, 'baselineFlows', None)
        shortest = getattr(self.testSet, 'shortestTimeout', None)
        longest = getattr(self.testSet, 'longestTimeout', None)
        for name, val in (('baselineFlows', baseline), ('shortestTimeout', shortest),
                          ('longestTimeout', longest)):
            if val is None:
                self.supported = False
                self.failed('{} was not established by TestCase_2'.format(name))
                return
        if not baseline:
            self.failed('baselineFlows is empty, there are no flow entries to hold')
            return

        def entry_tokens(entry):
            if not isinstance(entry, dict):
                return [str(entry).strip().lower()]
            tokens = []
            for key in ('match', 'actions'):
                val = entry.get(key)
                if val is None:
                    continue
                if isinstance(val, dict):
                    vals = [str(v) for v in val.values()]
                elif isinstance(val, (list, tuple)):
                    vals = [str(v) for v in val]
                else:
                    vals = [str(val)]
                tokens.extend(v.strip().lower() for v in vals if v.strip())
            return tokens

        def timeouts_ok(entry, line):
            if not isinstance(entry, dict):
                return True
            for key in ('idle_timeout', 'hard_timeout'):
                want = entry.get(key)
                if want is None or key not in line:
                    continue
                found = re.search(r'{}[=:\s]*(\d+)'.format(key), line)
                if found and int(found.group(1)) != int(want):
                    return False
            return True

        def check_table(text):
            lines = [ln.strip().lower() for ln in text.splitlines() if 'actions:' in ln]
            problems = []
            if len(lines) != len(baseline):
                problems.append('flow count {} != baseline {}'.format(len(lines), len(baseline)))
            remaining = list(lines)
            for entry in baseline:
                tokens = entry_tokens(entry)
                hit = None
                for ln in remaining:
                    if all(tok in ln for tok in tokens) and timeouts_ok(entry, ln):
                        hit = ln
                        break
                if hit is None:
                    problems.append('baseline entry missing or changed: {}'.format(entry))
                else:
                    remaining.remove(hit)
            return problems

        dutA.mode('#')
        self.log(dutA.cmd('show openflow status'))
        margin = 10
        interval = 5
        duration = int(longest) + margin
        start = time.time()
        polls = 0
        bad_polls = []
        ok_after_shortest = 0
        ok_after_longest = 0
        last_output = ''
        while True:
            elapsed = time.time() - start
            output = dutA.cmd('show openflow flows', log=False)
            last_output = output
            polls += 1
            problems = check_table(output)
            if problems:
                bad_polls.append((int(elapsed), problems))
            else:
                if elapsed > int(shortest):
                    ok_after_shortest += 1
                if elapsed > int(longest):
                    ok_after_longest += 1
            if elapsed >= duration:
                break
            time.sleep(interval)

        self.log('OBSERVED: {} polls over {}s, {} bad polls; last table:\n{}'.format(
            polls, duration, len(bad_polls), last_output))
        if polls == 0 or '%' in last_output:
            self.failed('show openflow flows could not be read: {}'.format(last_output.strip()[:80]))
            return
        if not bad_polls:
            self.passed('All {} polls held all {} baseline flow entries with the same matches, actions and '
                        'timeouts'.format(polls, len(baseline)))
        else:
            self.failed('{} of {} polls deviated from baselineFlows, first at {}s: {}'.format(
                len(bad_polls), polls, bad_polls[0][0], '; '.join(bad_polls[0][1])))
        if ok_after_shortest > 0:
            self.passed('{} polls after shortestTimeout {}s still held every baseline entry'.format(
                ok_after_shortest, shortest))
        else:
            self.failed('No clean poll after shortestTimeout {}s: entries did not persist'.format(shortest))
        if ok_after_longest > 0:
            self.passed('{} polls after longestTimeout {}s still held every baseline entry'.format(
                ok_after_longest, longest))
        else:
            self.failed('No clean poll after longestTimeout {}s: entries did not persist'.format(longest))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        dutA.mode(')#')
        dutA.cmd('interface vlan2000')
        dutA.cmd('no shutdown')
        dutA.mode('#')


class TestCase_6(ATTestCase.TestCase):
    testCaseDesc = 'While the controller is still unreachable, resend the flow F and flow D bursts with Scapy and capture on every egress data port.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.6'
    ckNeeds = ['baselineFlows', 'shortestTimeout', 'longestTimeout', 'preInterruptForwarding']
    skipIfExcl = True
    testCaseMethod = 'While the controller is still unreachable, resend the flow F and flow D bursts with Scapy and capture on every egress data port.\n'
    testCaseMethod += "Verify: Flow F is received on the same egress port as in preInterruptForwarding (from step 4), with received count equal to sent count. Flow D is received on no egress port. The retained entries' packet counters increase by the sent counts.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
