class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = "Restore the controller connection. Install the flow F forward entry and the flow D drop entry again, with timeouts shorter than the planned interruption, and record each entry's install time. Interrupt the controller connection. Send flows F and D before their timeouts elapse and again after they elapse, capturing on every egress data port. Then restore the connection."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.15'
    ckNeeds = ['baselineFlows', 'shortestTimeout', 'longestTimeout', 'preInterruptForwarding', 'intendedFlows']
    skipIfExcl = True
    testCaseMethod = "Restore the controller connection. Install the flow F forward entry and the flow D drop entry again, with timeouts shorter than the planned interruption, and record each entry's install time. Interrupt the controller connection. Send flows F and D before their timeouts elapse and again after they elapse, capturing on every egress data port. Then restore the connection.\n"
    testCaseMethod += 'Verify: Before the timeouts elapse, flow F is forwarded and flow D is dropped. Once the timeouts have elapsed, the entries are absent from the DUT flow table, and flow F is no longer received on any egress data port: it is handled as unmatched traffic under the secure fail mode. The controller reconnects after the restore.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # The controller link (vlan2000) is brought up so the controller is connected at the start.
        dutA.mode(')#')
        dutA.cmd('interface vlan2000')
        dutA.cmd('no shutdown')
        dutA.mode('#')

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 79-85
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 16: Restore the controller connection. Install the flow F forward entry and the flow D drop entry again, with timeouts shorter than the planned interruption, and record each entry's install time. Interrupt the controller connection. Send flows F and D before their timeouts elapse and again after they elapse, capturing on every egress data port. Then restore the connection.")
        import time
        for name in self.ckNeeds:
            if getattr(self.testSet, name, None) is None:
                self.supported = False
                self.failed('{} was not established by an earlier case'.format(name))
                return

        dutA.mode('#')
        probe = dutA.cmd('show openflow status')
        if 'Invalid input' in probe or 'Unrecognized command' in probe:
            self.supported = False
            self.failed('{} does not support openflow: {}'.format(dutA.name, probe.strip()[:80]))
            return

        ethZ = getattr(tb, 'ethZ', None)
        if ethZ is None:
            self.failed('controller interface on the testbox is not bound, cannot install flows')
            return
        dut_ip = ethZ.get_ipv4_addr(2)

        def controller_up():
            dutA.mode('#')
            text = dutA.cmd('show openflow status', log=False).lower()
            return 'connected' in text and 'disconnected' not in text

        def wait_controller(want, limit=120):
            start = time.time()
            while time.time() - start < limit:
                if controller_up() == want:
                    return True
                time.sleep(2)
            return False

        def set_link(up):
            dutA.mode(')#')
            dutA.cmd('interface vlan2000')
            dutA.cmd('no shutdown' if up else 'shutdown')
            dutA.mode('#')

        macs = {'F': ('00:00:aa:00:00:0f', '00:00:bb:00:00:0f'),
                'D': ('00:00:aa:00:00:0d', '00:00:bb:00:00:0d')}
        actions = {'F': 'in_port', 'D': 'drop'}
        timeout = max(15, min(int(self.testSet.shortestTimeout), 20))

        # Restore the controller connection first
        set_link(True)
        if not wait_controller(True):
            self.failed('controller did not connect before the flows were installed')
            return

        installed = {}
        for flow in ('F', 'D'):
            src, dst = macs[flow]
            spec = 'hard_timeout={},priority=100,dl_src={},dl_dst={},actions={}'.format(
                timeout, src, dst, actions[flow])
            (stdout, stderr) = tb.cmd('ovs-ofctl -O OpenFlow10 add-flow tcp:{}:6653 "{}"'.format(dut_ip, spec))
            installed[flow] = time.time()
            self.log('Flow {} install: {} {}'.format(flow, stdout, stderr))

        flows_before = dutA.cmd('show openflow flows')
        self.log(flows_before)

        def send_and_count(tag):
            counts = {}
            for flow in ('F', 'D'):
                src, dst = macs[flow]
                pcap = '/tmp/c15_{}_{}.pcap'.format(tag, flow)
                bpf = 'inbound and ether src {}'.format(src)
                sub = tb.start_tcpdump(ethA.name, pcap, bpf)
                time.sleep(2)
                sendp([Ether(src=src, dst=dst) / IP()] * 5, iface=ethA.name, verbose=0, inter=0.05)
                time.sleep(2)
                tb.stop_tcpdump(sub)
                try:
                    counts[flow] = len(rdpcap(pcap))
                except Exception:
                    counts[flow] = 0
            return counts

        # Interrupt the controller connection (controller VLAN interface shut)
        set_link(False)
        down = wait_controller(False)
        before = send_and_count('before')
        flows_during = dutA.cmd('show openflow flows')
        self.log(flows_during)

        remaining = timeout + 5 - (time.time() - min(installed.values()))
        if remaining > 0:
            time.sleep(remaining)
        after = send_and_count('after')
        flows_after = dutA.cmd('show openflow flows').lower()

        # Restore the connection
        set_link(True)
        reconnected = wait_controller(True)
        output = 'down={} before={} after={} reconnected={}\n{}'.format(
            down, before, after, reconnected, flows_after)
        self.log('OBSERVED: {}'.format(output))

        if not down:
            self.failed('controller connection did not drop during the interruption')
            return
        if before['F'] > 0:
            self.passed('flow F forwarded before timeout ({} frames received)'.format(before['F']))
        else:
            self.failed('flow F not forwarded before timeout, {} frames received'.format(before['F']))
        if before['D'] == 0:
            self.passed('flow D dropped before timeout (0 frames received)')
        else:
            self.failed('flow D not dropped before timeout, {} frames received'.format(before['D']))
        if macs['F'][0] not in flows_after and macs['D'][0] not in flows_after:
            self.passed('flow F and flow D entries absent from flow table after timeouts')
        else:
            self.failed('flow entries still present in flow table after the timeouts elapsed')
        if after['F'] == 0:
            self.passed('flow F no longer received after timeout under secure fail mode (0 frames)')
        else:
            self.failed('flow F still received after timeout, {} frames'.format(after['F']))
        if reconnected:
            self.passed('controller reconnected after the connection was restored')
        else:
            self.failed('controller did not reconnect after the connection was restored')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # Mirror of the interruption done in main(): bring the controller link back.
        dutA.mode(')#')
        dutA.cmd('interface vlan2000')
        dutA.cmd('no shutdown')
        dutA.mode('#')


class TestCase_16(ATTestCase.TestCase):
    testCaseDesc = "Read 'show openflow status' and running-config in the default configuration (secure fail mode, non-rule-expiry option absent)."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T44333, 9003.44333.16'
    testCaseMethod = "Read 'show openflow status' and running-config in the default configuration (secure fail mode, non-rule-expiry option absent).\n"
    testCaseMethod += 'Verify: The OpenFlow status reports the fail mode as secure and reports the non-rule-expiry option as not enabled. Running-config matches.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # The default configuration is what this step reads: make sure no fail-mode
        # option is configured so the secure default applies.
        dutA.mode(')#')
        dutA.cmd('no openflow fail-mode')
        dutA.mode('#')

    def main(self):
        # ART 1346_swi_misc/library_1346.py lines 995-1003
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 17: Read 'show openflow status' and running-config in the default configuration (secure fail mode, non-rule-expiry option absent).")
        dutA.mode('#')
        status = dutA.cmd('show openflow status')
        if 'Invalid input' in status or 'Unrecognized command' in status:
            self.supported = False
            self.failed('{} does not support openflow status: {}'.format(dutA.name, status.strip()[:80]))
            return
        running = dutA.cmd('show running-config')
        output = 'STATUS:\n{}\nRUNNING:\n{}'.format(status, running)
        self.log('OBSERVED: {}'.format(output))

        status_lines = [line.strip().lower() for line in status.splitlines()]
        run_lines = [line.strip().lower() for line in running.splitlines()]

        # Fail mode in status: secure must be reported, standalone must not be.
        fail_lines = [line for line in status_lines if 'fail' in line and 'mode' in line]
        if fail_lines:
            if any('secure' in line for line in fail_lines) and not any('standalone' in line for line in fail_lines):
                self.passed('show openflow status reports fail mode secure: {}'.format(fail_lines[0]))
            else:
                self.failed('show openflow status fail mode is not secure: {}'.format(fail_lines[0]))
        else:
            self.failed('show openflow status does not show a fail mode line')

        # Non-rule-expiry option must not be reported as enabled.
        nre_lines = [line for line in status_lines if 'expiry' in line or 'expire' in line]
        if not nre_lines:
            self.passed('show openflow status does not report non-rule-expiry option as enabled')
        elif any(('not enabled' in line or 'disabled' in line or line.endswith('off') or
                  line.endswith('no') or line.endswith('false')) for line in nre_lines):
            self.passed('show openflow status reports non-rule-expiry as not enabled: {}'.format(nre_lines[0]))
        else:
            self.failed('show openflow status reports non-rule-expiry as enabled: {}'.format(nre_lines[0]))

        # Running-config must match the default: no non-rule-expiry or standalone setting.
        of_lines = [line for line in run_lines if line.startswith('openflow') or line.startswith('service openflow')]
        bad = [line for line in of_lines if 'standalone' in line or 'expiry' in line or 'expire' in line]
        if 'service openflow' not in run_lines:
            self.failed('running-config does not contain service openflow')
        elif bad:
            self.failed('running-config contains non-default openflow option: {}'.format(bad[0]))
        else:
            self.passed('running-config shows default secure fail mode with no non-rule-expiry option')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        # configure() only ensured the default; nothing else was changed.
        dutA.mode('#')


