        # ART 1346_swi_misc/library_1346.py lines 79-85
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        self.log("STEP 22: After the reload, install timed entries from the controller (forward flow F and drop flow D, each with idle and hard timeouts) and record them. Interrupt the controller connection for longer than the longest timeout, polling 'show openflow flows' and resending flows F and D. Then restore the connection.")
        import time

        for name in self.ckNeeds:
            if getattr(self.testSet, name, None) is None:
                self.supported = False
                self.failed('{} was not established by an earlier test case'.format(name))
                return

        longest = int(self.testSet.longestTimeout)
        baseline = self.testSet.baselineFlows
        interrupt = longest + 15

        dutA.mode('#')
        probe = dutA.cmd('show openflow status')
        if 'Invalid input' in probe or 'Unrecognized command' in probe:
            self.supported = False
            self.failed('{} does not support openflow: {}'.format(dutA.name, probe.strip()[:80]))
            return

        # Record the timed entries as they stand before the interruption
        before = dutA.cmd('show openflow flows')
